var text = String(input.diffSummary || input.text || "");
var lower = text.toLowerCase();
var type = "chore";
if (/fix|bug|修复|补丁/.test(lower)) type = "fix";
else if (/feat|feature|add|新增|功能/.test(lower)) type = "feat";
else if (/doc|文档|readme/.test(lower)) type = "docs";
else if (/test|测试/.test(lower)) type = "test";
else if (/refactor|重构/.test(lower)) type = "refactor";
else if (/perf|性能/.test(lower)) type = "perf";
var subject = text.replace(/\s+/g, " ").trim().slice(0, 60);
return { message: type + ": " + subject, type: type, note: "rule-based suggestion; review before using" };
